import json
import graphviz
import os

# Load data
with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

# Initialize Digraph
dot = graphviz.Digraph('Event-Driven Architecture', format='png')
dot.attr(
    rankdir='LR',
    nodesep='0.6',
    ranksep='1.0',
    splines='spline',
    fontname='Helvetica',
    fontsize='14',
    label='Event-Driven Architecture Panorama\n(Including Routing, Error Handling, Schema Validation & Monitoring)',
    labelloc='t'
)

# Colors and styles
C_MICROSERVICE = {'shape': 'component', 'style': 'filled', 'fillcolor': '#e1f5fe', 'color': '#0288d1', 'fontname': 'Helvetica-Bold'}
C_TOPIC = {'shape': 'cylinder', 'style': 'filled', 'fillcolor': '#e8f5e9', 'color': '#388e3c', 'fontname': 'Helvetica'}
C_DLQ = {'shape': 'cylinder', 'style': 'filled,dashed', 'fillcolor': '#ffebee', 'color': '#d32f2f', 'fontname': 'Helvetica-Bold'}
C_SCHEMA_REG = {'shape': 'note', 'style': 'filled', 'fillcolor': '#fff8e1', 'color': '#ffa000', 'fontname': 'Helvetica-Bold'}
C_MONITORING = {'shape': 'box3d', 'style': 'filled,dashed', 'fillcolor': '#f3e5f5', 'color': '#8e24aa', 'fontname': 'Helvetica'}

E_PRODUCE = {'color': '#424242', 'style': 'solid', 'penwidth': '1.5'}
E_CONSUME = {'color': '#424242', 'style': 'solid', 'penwidth': '1.5'}
E_SCHEMA = {'color': '#ff8f00', 'style': 'dashed', 'penwidth': '1.0', 'dir': 'both'}
E_DLQ = {'color': '#d32f2f', 'style': 'bold,dashed', 'penwidth': '2.0'}
E_MONITOR = {'color': '#8e24aa', 'style': 'dotted', 'penwidth': '1.0'}

# 1. Microservices
with dot.subgraph(name='cluster_microservices') as c:
    c.attr(label='Microservices', style='dashed', color='grey')
    for svc in data['microservices']['data']:
        # include some extra info in label
        label = f"{svc['name']}\nRole: {svc['role']}"
        c.node(svc['id'], label, **C_MICROSERVICE)

# 2. Schema Registry
dot.node('schema-registry', 'Schema Registry\n(Validation Checkpoint)', **C_SCHEMA_REG)

# 3. Kafka Topics (Central Hub)
with dot.subgraph(name='cluster_kafka') as c:
    c.attr(label='Kafka Event Hub', style='filled', fillcolor='#f1f8e9', color='#aed581', penwidth='2')
    # Normal topics
    for topic in data['kafka_topics']['data']:
        if topic['category'] != 'dlq':
            label = f"{topic['topic_name']}\n(P:{topic['partitions']}|R:{topic['replication_factor']})"
            c.node(topic['topic_name'], label, **C_TOPIC)

# 4. DLQ Topics
with dot.subgraph(name='cluster_dlq') as c:
    c.attr(label='Dead Letter Queues\n(Error Paths)', style='filled', fillcolor='#ffebee', color='#e57373', penwidth='2')
    for topic in data['kafka_topics']['data']:
        if topic['category'] == 'dlq':
            c.node(topic['topic_name'], topic['topic_name'], **C_DLQ)

# 5. Monitoring
mon_nodes = set()
for m in data['monitoring_alerting']['data']:
    if m['source'] not in [s['id'] for s in data['microservices']['data']] and m['source'] != 'schema-registry' and m['source'] != 'kafka-cluster':
        mon_nodes.add(m['source'])
    if m['target'] not in [s['id'] for s in data['microservices']['data']] and m['target'] != 'schema-registry' and m['target'] != 'kafka-cluster':
        mon_nodes.add(m['target'])

with dot.subgraph(name='cluster_monitoring') as c:
    c.attr(label='Observability & Alerting', style='dashed', color='#ab47bc')
    for node in mon_nodes:
        c.node(node, node.upper(), **C_MONITORING)

# Add "kafka-cluster" generic node for monitoring if needed, or link monitoring from cluster_kafka
dot.node('kafka-cluster', 'Kafka Cluster Metrics', shape='point', width='0')
# Link dummy node to cluster
dot.edge('kafka-cluster', 'prometheus', style='invis') # Just to keep layout

# Edges
# Event Flows
for flow in data['event_flows']['data']:
    src = flow['source']
    tgt = flow['target']
    ftype = flow['flow_type']

    if ftype == 'produce':
        dot.edge(src, tgt, label=' produces', **E_PRODUCE)
    elif ftype == 'consume':
        dot.edge(src, tgt, label=' consumes', **E_CONSUME)
    elif ftype == 'dlq-produce':
        dot.edge(src, tgt, label=' max retries exc.', **E_DLQ)
    elif ftype == 'schema-lookup':
        dot.edge(src, tgt, label=' validates', **E_SCHEMA)

# Retry Policies - add self loops or annotations
for rp in data['retry_policies']['data']:
    if rp['strategy'] != 'none':
        # Add a self-loop to show retry path
        svc_id = rp['service_id']
        label = f"Retry: {rp['strategy']}\nMax: {rp['max_retries']}"
        dot.edge(svc_id, svc_id, label=label, color='#f57c00', fontcolor='#f57c00', style='dashed', penwidth='1.5')

# Monitoring Links
for m in data['monitoring_alerting']['data']:
    src = m['source']
    tgt = m['target']
    label = m['metric_type']
    if label == 'alert-rule':
        edge_style = {'color': '#d32f2f', 'style': 'solid', 'penwidth': '1.5'}
    elif label == 'notification':
        edge_style = {'color': '#e64a19', 'style': 'bold', 'penwidth': '2.0'}
    else:
        edge_style = E_MONITOR
    dot.edge(src, tgt, label=f" {label}", **edge_style)

# Save
dot.render('/app/output/result', format='png', cleanup=True)
print("Saved to /app/output/result.png")

