import json
import graphviz

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

dot = graphviz.Digraph('Event-Driven Architecture', format='png')
dot.attr(
    rankdir='LR',
    nodesep='0.8',
    ranksep='1.2',
    splines='spline',
    compound='true',
    fontname='Helvetica',
    fontsize='16',
    label='Event-Driven Architecture Panorama\n(Routing, Error Handling, Schema Validation & Monitoring)',
    labelloc='t'
)

C_MICROSERVICE = {'shape': 'component', 'style': 'filled', 'fillcolor': '#e1f5fe', 'color': '#0288d1', 'fontname': 'Helvetica-Bold'}
C_TOPIC = {'shape': 'cylinder', 'style': 'filled', 'fillcolor': '#e8f5e9', 'color': '#388e3c', 'fontname': 'Helvetica'}
C_DLQ = {'shape': 'cylinder', 'style': 'filled,dashed', 'fillcolor': '#ffebee', 'color': '#d32f2f', 'fontname': 'Helvetica-Bold'}
C_SCHEMA_REG = {'shape': 'note', 'style': 'filled', 'fillcolor': '#fff8e1', 'color': '#ffa000', 'fontname': 'Helvetica-Bold'}
C_MONITORING = {'shape': 'box3d', 'style': 'filled', 'fillcolor': '#f3e5f5', 'color': '#8e24aa', 'fontname': 'Helvetica-Bold'}
C_ALERTING = {'shape': 'octagon', 'style': 'filled,dashed', 'fillcolor': '#fce4ec', 'color': '#c2185b', 'fontname': 'Helvetica'}

E_PRODUCE = {'color': '#1565c0', 'style': 'solid', 'penwidth': '2.0'}
E_CONSUME = {'color': '#2e7d32', 'style': 'solid', 'penwidth': '2.0'}
E_SCHEMA = {'color': '#f57c00', 'style': 'dashed', 'penwidth': '1.5'}
E_DLQ = {'color': '#d32f2f', 'style': 'bold,dashed', 'penwidth': '2.5'}
E_MONITOR = {'color': '#8e24aa', 'style': 'dotted', 'penwidth': '1.5'}

# 1. Microservices
with dot.subgraph(name='cluster_microservices') as c:
    c.attr(label='Microservices', style='dashed', color='#0288d1', fontname='Helvetica-Bold')
    for svc in data['microservices']['data']:
        label = f"{svc['name']}\nRole: {svc['role']}"
        c.node(svc['id'], label, **C_MICROSERVICE)

# 2. Schema Registry
dot.node('schema-registry', 'Schema Registry\n(Validation Checkpoint)', **C_SCHEMA_REG)

# 3. Kafka Topics (Central Hub)
with dot.subgraph(name='cluster_kafka') as c:
    c.attr(label='Kafka Event Hub', style='filled', fillcolor='#f1f8e9', color='#689f38', penwidth='2', fontname='Helvetica-Bold')
    for topic in data['kafka_topics']['data']:
        if topic['category'] != 'dlq':
            label = f"{topic['topic_name']}\n(P:{topic['partitions']} | R:{topic['replication_factor']})"
            c.node(topic['topic_name'], label, **C_TOPIC)

# 4. DLQ Topics
with dot.subgraph(name='cluster_dlq') as c:
    c.attr(label='Dead Letter Queues\n(Error Paths)', style='filled', fillcolor='#ffebee', color='#e57373', penwidth='2', fontname='Helvetica-Bold')
    for topic in data['kafka_topics']['data']:
        if topic['category'] == 'dlq':
            c.node(topic['topic_name'], topic['topic_name'], **C_DLQ)

# 5. Monitoring & Alerting Nodes
mon_nodes = set()
for m in data['monitoring_alerting']['data']:
    for n in (m['source'], m['target']):
        if n not in [s['id'] for s in data['microservices']['data']] and n not in ('schema-registry', 'kafka-cluster'):
            mon_nodes.add(n)

with dot.subgraph(name='cluster_monitoring') as c:
    c.attr(label='Observability & Alerting', style='dashed', color='#ab47bc', fontname='Helvetica-Bold')
    for node in mon_nodes:
        if node in ('slack-channel', 'pagerduty', 'alertmanager'):
            c.node(node, node.upper(), **C_ALERTING)
        else:
            c.node(node, node.upper(), **C_MONITORING)

# Virtual node for Kafka cluster metrics representation
dot.node('kafka-cluster', 'Kafka Cluster', shape='Mrecord', style='filled', fillcolor='#f1f8e9', color='#388e3c')

# Edges
# Event Flows
for flow in data['event_flows']['data']:
    src = flow['source']
    tgt = flow['target']
    ftype = flow['flow_type']

    if ftype == 'produce':
        dot.edge(src, tgt, label=' produces', **E_PRODUCE)
    elif ftype == 'consume':
        dot.edge(src, tgt, label=f" consumes\n({flow.get('consumer_group', '')})", **E_CONSUME)
    elif ftype == 'dlq-produce':
        dot.edge(src, tgt, label=' retry maxed', **E_DLQ)
    elif ftype == 'schema-lookup':
        # bidirectional is indicated in JSON, drawing as standard edge but no arrows needed or both
        dir_val = 'both' if flow.get('direction') == 'bidirectional' else 'forward'
        dot.edge(src, tgt, label=' validates schema', dir=dir_val, **E_SCHEMA)

# Retry Policies (Self Loops)
for rp in data['retry_policies']['data']:
    if rp['strategy'] != 'none':
        svc_id = rp['service_id']
        label = f"Retry Policy:\n{rp['strategy']}\nMax Retries: {rp['max_retries']}"
        dot.edge(svc_id, svc_id, label=label, color='#d84315', fontcolor='#d84315', style='bold,dashed', penwidth='2.0')

# Monitoring Links
for m in data['monitoring_alerting']['data']:
    src = m['source']
    tgt = m['target']
    m_type = m['metric_type']
    m_name = m['metric_name']

    if m_type == 'alert-rule':
        edge_style = {'color': '#c2185b', 'style': 'solid', 'penwidth': '2.0'}
        label = f" alert:\n{m_name}"
    elif m_type == 'notification':
        edge_style = {'color': '#c2185b', 'style': 'bold', 'penwidth': '2.5'}
        label = f" notify:\n{m_name}"
    else:
        edge_style = E_MONITOR
        label = f" {m_type}:\n{m_name}"

    dot.edge(src, tgt, label=label, fontsize="10", **edge_style)

# Add an invisible edge to improve layout flow if needed
dot.edge('schema-registry', 'prometheus', style='invis')

dot.render('/app/output/result', format='png', cleanup=True)
